INSERT INTO public.diaries (
  couple_id,
  author_id,
  title,
  content,
  diary_date,
  mood,
  tags
)
SELECT
  vars.couple_id,
  vars.author_id,
  diary_rows.title,
  diary_rows.content,
  diary_rows.diary_date,
  'love',
  ARRAY[]::text[]
FROM diary_rows
CROSS JOIN vars
WHERE NOT EXISTS (
  SELECT 1
  FROM public.diaries existing
  WHERE existing.couple_id = vars.couple_id
    AND existing.author_id = vars.author_id
    AND existing.diary_date = diary_rows.diary_date
    AND existing.deleted_at IS NULL
)
ORDER BY diary_rows.diary_date
RETURNING id, diary_date, title, mood;

COMMIT;
